class Solution:
    def reinitializePermutation(self, n: int) -> int:
        perm = list(range(n))
        half = n // 2
        steps = 0
        while True:
            nxt = [perm[i // 2] if i % 2 == 0 else perm[half + (i - 1) // 2] for i in range(n)]
            perm = nxt
            steps += 1
            if all(perm[i] == i for i in range(n)):
                return steps

