class Solution {
public:
    int reinitializePermutation(int n) {
        int half = n / 2;
        vector<int> perm(n), target(n);
        iota(perm.begin(), perm.end(), 0);
        target = perm;
        int steps = 0;
        do {
            vector<int> nxt(n);
            for (int i = 0; i < n; ++i)
                nxt[i] = (i % 2 == 0) ? perm[i / 2] : perm[half + (i - 1) / 2];
            perm = move(nxt);
            ++steps;
        } while (perm != target);
        return steps;
    }
};

