class Solution {
    public int reinitializePermutation(int n) {
        int half = n / 2;
        int[] perm = new int[n];
        for (int i = 0; i < n; i++) perm[i] = i;
        int steps = 0;
        do {
            int[] next = new int[n];
            for (int i = 0; i < n; i++)
                next[i] = (i % 2 == 0) ? perm[i / 2] : perm[half + (i - 1) / 2];
            perm = next;
            steps++;
        } while (!checkSorted(perm));
        return steps;
    }

    private boolean checkSorted(int[] a) {
        for (int i = 0; i < a.length; i++)
            if (a[i] != i) return false;
        return true;
    }
}

