var reinitializePermutation = function(n) {
    const half = n / 2;
    let perm = Array.from({ length: n }, (_, i) => i);
    let steps = 0;
    do {
        perm = perm.map((_, i) => (i % 2 === 0 ? perm[i / 2] : perm[half + (i - 1) / 2]));
        steps++;
    } while (perm.some((v, i) => v !== i));
    return steps;
};

